from __future__ import annotations

from itertools import combinations


def vertex_cover_yes(instance: dict) -> bool:
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k < 0:
        return False
    # try all subsets of size <= k
    for size in range(0, min(k, n) + 1):
        for subset in combinations(range(n), size):
            chosen = set(subset)
            if all(u in chosen or v in chosen for u, v in edges):
                return True
    return False


def clique_yes(instance: dict) -> bool:
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k <= 0:
        return True
    if k > n:
        return False
    adj = set()
    for u, v in edges:
        adj.add(frozenset((u, v)))
    for subset in combinations(range(n), k):
        if all(frozenset((subset[i], subset[j])) in adj
               for i in range(len(subset)) for j in range(i + 1, len(subset))):
            return True
    return False
